<template>
  <ManagementLayout>
    <div class="page-heading"><div><p class="eyebrow">GOOD FOOD, GREAT FIRST IMPRESSIONS</p><h1>Menu items</h1><p>Your dishes, thoughtfully organized and ready to discover.</p></div><router-link to="/addmenu" class="button primary"><AppIcon name="plus" /> Add menu item</router-link></div>
    <p v-if="error" class="notice error" role="alert">{{ error }} <button class="text-button" @click="load">Try again</button></p>
    <section class="panel table-panel"><div class="table-toolbar"><div><h2>On the menu <span class="count-badge">{{ menus.length }}</span></h2><p>Make every item look as good as it tastes.</p></div><div class="toolbar-filters"><label class="search-field"><AppIcon name="search" /><input v-model="search" placeholder="Search menu items…" aria-label="Search menu items" /></label><select v-model="restaurantFilter" aria-label="Filter by restaurant"><option value="">All restaurants</option><option v-for="restaurant in restaurants" :key="restaurant.id" :value="String(restaurant.id)">{{ restaurant.name }}</option></select></div></div>
      <p v-if="loading" class="loading-state">Loading your menu…</p><div v-else-if="!error && !filtered.length" class="empty-state"><span class="icon-tile large"><AppIcon name="menu" /></span><h2>{{ search||restaurantFilter ? 'Nothing on this page yet.' : 'Let’s put something delicious here.' }}</h2><p>{{ search||restaurantFilter ? 'Try changing your search or filter.' : 'Add your first dish and start building your menu.' }}</p><router-link v-if="!search&&!restaurantFilter" to="/addmenu" class="button primary">Create a menu item <AppIcon name="arrow" /></router-link></div>
      <div v-else-if="filtered.length" class="table-scroll"><table class="data-table"><thead><tr><th>Menu item</th><th>Restaurant</th><th>Category</th><th>Price</th><th class="align-right">Actions</th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id"><td><div class="table-identity"><img :src="item.image||'/images/menu-placeholder.svg'" :alt="item.name" /><div><strong>{{ item.name }}</strong><small class="truncate-description">{{ item.description||'No description added' }}</small></div></div></td><td>{{ restaurantName(item.restaurant_id) }}</td><td><span class="pill neutral">{{ item.category }}</span></td><td class="price-cell">{{ money(item.price) }}</td><td><div class="row-actions"><router-link :to="`/updatemenu/${item.id}`" class="icon-button" :aria-label="`Edit ${item.name}`"><AppIcon name="edit" /></router-link><button class="icon-button delete-action" :aria-label="`Delete ${item.name}`" @click="target=item"><AppIcon name="trash" /></button></div></td></tr></tbody></table></div>
      <div v-if="filtered.length" class="table-bottom">Showing {{ filtered.length }} of {{ menus.length }} menu items <span>Changes appear on your public menus.</span></div>
    </section><ConfirmDialog :open="Boolean(target)" title="Remove this menu item?" :message="target ? `${target.name} will be removed from the menu.` : ''" :busy="deleting" @cancel="target=null" @confirm="remove" />
  </ManagementLayout>
</template>
<script>
import ManagementLayout from '../shared/ManagementLayout.vue';import AppIcon from '../shared/AppIcon.vue';import ConfirmDialog from '../shared/ConfirmDialog.vue';import http from '../../services/http';
export default{components:{ManagementLayout,AppIcon,ConfirmDialog},data:()=>({menus:[],restaurants:[],search:'',restaurantFilter:'',loading:true,error:'',target:null,deleting:false}),computed:{filtered(){const q=this.search.toLowerCase().trim();return this.menus.filter(item=>(!this.restaurantFilter||String(item.restaurant_id)===this.restaurantFilter)&&`${item.name} ${item.description} ${item.category}`.toLowerCase().includes(q));}},mounted(){this.load();},methods:{money(value){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(value)||0);},restaurantName(id){return this.restaurants.find(item=>Number(item.id)===Number(id))?.name||'Restaurant';},async load(){this.error='';this.loading=true;try{const [menus,restaurants]=await Promise.all([http.get('/menus?mine=1'),http.get('/restaurant?mine=1')]);this.menus=menus.data;this.restaurants=restaurants.data;}catch(error){this.error=error.response?.data?.error||'We couldn’t load your menu.';}finally{this.loading=false;}},async remove(){if(!this.target||this.deleting)return;this.deleting=true;try{await http.delete(`/menus/${this.target.id}`);this.target=null;await this.load();}catch(error){this.target=null;this.error=error.response?.data?.error||'We couldn’t delete this menu item.';}finally{this.deleting=false;}}}};
</script>
